#include <stdio.h>
#include <string.h>

// Assuming the following types are defined:
// typedef struct _ImageInfo ImageInfo;
// typedef struct _Image Image;
// typedef struct _ExceptionInfo ExceptionInfo;
// typedef int MagickBooleanType;
// typedef int MagickStatusType;
// typedef int MagickSizeType;

#define MagickTrue 1
#define MagickFalse 0

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images, const char *filename, ExceptionInfo *exception) {
  if (image_info == NULL || images == NULL || filename == NULL || exception == NULL) {
    return MagickFalse;
  }

  // Clone the image info
  ImageInfo *clone_info = CloneImageInfo(image_info);
  if (clone_info == NULL) {
    return MagickFalse;
  }

  // Prepare filenames for each image
  MagickSizeType number_images = GetImageListLength(images);
  if (number_images == 0) {
    DestroyImageInfo(clone_info);
    return MagickFalse;
  }

  // Set up the image info
  clone_info->adjoin = MagickFalse;

  // Ensure consistent scene numbers across images
  MagickSizeType scene = 0;
  Image *image = images;
  while (image != NULL) {
    image->scene = scene++;
    image = image->next;
  }

  // Iterate through the image list and write each image
  image = images;
  while (image != NULL) {
    // Prepare the filename for the current image
    char *output_filename = NULL;
    ssize_t filename_length = FormatImageFilename(clone_info, image, 0, &output_filename, exception);
    if (filename_length <= 0 || output_filename == NULL) {
      DestroyImageInfo(clone_info);
      return MagickFalse;
    }

    // Write the image to the output file
    MagickBooleanType status = WriteImage(clone_info, image, output_filename, exception);
    if (status == MagickFalse) {
      DestroyImageInfo(clone_info);
      return MagickFalse;
    }

    // Clean up
    if (output_filename != NULL) {
      free(output_filename);
    }

    image = image->next;
  }

  // Clean up
  DestroyImageInfo(clone_info);
  return MagickTrue;
}
